import { object, string, optional, array, number } from '../../runtime/validation/index.js';
import { contract } from '../../runtime/Contracts.js';

/**
 * History module — EventBus contracts.
 *
 * These events describe the lifecycle of an operation in the history log:
 * recorded (added), undone (reversed), redone (re-applied), and log-ready
 * (initial hydration complete).
 *
 * Sync-specific events (OPTIMISTIC_ACTION_RECORDED / _ACKED / _FAILED) are
 * NOT defined here — they belong to the optimistic-sync module. The history
 * module is sync-agnostic.
 */
export const HistoryContracts = {
    HISTORY_OP_RECORDED: contract({
        version: 1,
        type: 'event',
        owner: 'history',
        lifecycle: 'active',
        stability: 'stable',
        compliance: 'public',
        description: 'Published when a new entry is appended to the history log'
    }, object({
        entry: object({
            id: string(),
            intent: string(),
            payload: optional(object()),
            status: string(),
            createdAt: number(),
            updatedAt: number(),
            meta: optional(object())
        })
    })),

    HISTORY_OP_UNDONE: contract({
        version: 1,
        type: 'event',
        owner: 'history',
        lifecycle: 'active',
        stability: 'stable',
        compliance: 'public',
        description: 'Published when the latest recorded entry is reversed via undo()'
    }, object({
        entry: object({
            id: string(),
            intent: string()
        }),
        cursor: string()
    })),

    HISTORY_OP_REDONE: contract({
        version: 1,
        type: 'event',
        owner: 'history',
        lifecycle: 'active',
        stability: 'stable',
        compliance: 'public',
        description: 'Published when a previously undone entry is re-applied via redo()'
    }, object({
        entry: object({
            id: string(),
            intent: string()
        }),
        cursor: string()
    })),

    HISTORY_LOG_READY: contract({
        version: 1,
        type: 'event',
        owner: 'history',
        lifecycle: 'active',
        stability: 'stable',
        compliance: 'public',
        description: 'Published when the history log finishes initial hydration from the store'
    }, object({
        count: number()
    }))
};

/**
 * HistoryStore — IDB adapter for the history module.
 *
 * Extracted verbatim from the former ActionLogService's IndexedDbActionStore
 * + MemoryActionStore. Parameterised by dbName + storeName so each consumer
 * (history default, optimistic-sync's continuation data, future mindmap ops)
 * can target its own IDB store.
 *
 * Storage layout: one record per entry, keyed by `entry.id`. Records carry
 * the full entry object (no joins, no indexes beyond the primary key).
 */

const DEFAULT_DB_NAME = 'csma-history';
const DEFAULT_STORE_NAME = 'ops';

export class HistoryStore {
    constructor({ dbName = DEFAULT_DB_NAME, storeName = DEFAULT_STORE_NAME } = {}) {
        this.dbName = dbName;
        this.storeName = storeName;
        this.db = null;
        this.supportsStorageEvents = false;
        this._backend = null;
    }

    init() {
        if (typeof indexedDB !== 'undefined') {
            this._backend = new IndexedDbHistoryBackend({
                dbName: this.dbName,
                storeName: this.storeName
            });
        } else {
            this._backend = new MemoryHistoryBackend();
        }
        this.supportsStorageEvents = this._backend.supportsStorageEvents;
        return this._backend.init();
    }

    getAll() {
        return this._backend.getAll();
    }

    put(entry) {
        return this._backend.put(entry);
    }

    delete(id) {
        return this._backend.delete(id);
    }

    clear() {
        return this._backend.clear();
    }
}

class IndexedDbHistoryBackend {
    constructor({ dbName, storeName }) {
        this.dbName = dbName;
        this.storeName = storeName;
        this.db = null;
        this.supportsStorageEvents = false;
    }

    init() {
        return new Promise((resolve, reject) => {
            const request = indexedDB.open(this.dbName, 1);
            request.onerror = () => reject(request.error);
            request.onsuccess = () => {
                this.db = request.result;
                resolve();
            };
            request.onupgradeneeded = (event) => {
                const db = event.target.result;
                if (!db.objectStoreNames.contains(this.storeName)) {
                    db.createObjectStore(this.storeName, { keyPath: 'id' });
                }
            };
        });
    }

    getAll() {
        return new Promise((resolve, reject) => {
            const tx = this.db.transaction(this.storeName, 'readonly');
            const store = tx.objectStore(this.storeName);
            const request = store.getAll();
            request.onerror = () => reject(request.error);
            request.onsuccess = () => {
                const result = request.result || [];
                result.sort((a, b) => b.createdAt - a.createdAt);
                resolve(result);
            };
        });
    }

    put(entry) {
        return new Promise((resolve, reject) => {
            const tx = this.db.transaction(this.storeName, 'readwrite');
            const store = tx.objectStore(this.storeName);
            const request = store.put(entry);
            request.onerror = () => reject(request.error);
            request.onsuccess = () => resolve();
        });
    }

    delete(id) {
        return new Promise((resolve, reject) => {
            const tx = this.db.transaction(this.storeName, 'readwrite');
            const store = tx.objectStore(this.storeName);
            const request = store.delete(id);
            request.onerror = () => reject(request.error);
            request.onsuccess = () => resolve();
        });
    }

    clear() {
        return new Promise((resolve, reject) => {
            const tx = this.db.transaction(this.storeName, 'readwrite');
            const store = tx.objectStore(this.storeName);
            const request = store.clear();
            request.onerror = () => reject(request.error);
            request.onsuccess = () => resolve();
        });
    }
}

class MemoryHistoryBackend {
    constructor() {
        this.items = new Map();
        this.supportsStorageEvents = false;
    }

    init() {
        return Promise.resolve();
    }

    async getAll() {
        return Array.from(this.items.values());
    }

    async put(entry) {
        this.items.set(entry.id, entry);
    }

    async delete(id) {
        this.items.delete(id);
    }

    async clear() {
        this.items.clear();
    }
}

export { DEFAULT_DB_NAME, DEFAULT_STORE_NAME };

/**
 * BroadcastSync — multi-tab synchronisation helper for the history module.
 *
 * Wraps BroadcastChannel (when available) so that multiple tabs sharing the
 * same history store (same dbName/storeName) reload from the store when one
 * tab writes. Single-tab leader election is intentionally out of scope for
 * v1 (see plan.md open question #3).
 *
 * Extracted from the former ActionLogService's BroadcastChannel wiring.
 */

const DEFAULT_CHANNEL_NAME = 'csma-history';

export class BroadcastSync {
    constructor({ channelName = DEFAULT_CHANNEL_NAME, onMessage } = {}) {
        this.channelName = channelName;
        this.onMessage = typeof onMessage === 'function' ? onMessage : null;
        this.channel = null;
        this._messageHandler = this._messageHandler.bind(this);
    }

    init() {
        if (typeof BroadcastChannel === 'undefined') {
            return;
        }
        this.channel = new BroadcastChannel(this.channelName);
        this.channel.addEventListener('message', this._messageHandler);
    }

    destroy() {
        if (!this.channel) return;
        this.channel.removeEventListener('message', this._messageHandler);
        this.channel.close();
        this.channel = null;
    }

    postMessage(message) {
        if (!this.channel) return;
        try {
            this.channel.postMessage(message);
        } catch (error) {
            console.warn('[BroadcastSync] postMessage failed:', error);
        }
    }

    _messageHandler(event) {
        if (typeof this.onMessage !== 'function') return;
        try {
            this.onMessage(event?.data, event);
        } catch (error) {
            console.warn('[BroadcastSync] onMessage handler threw:', error);
        }
    }
}

export { DEFAULT_CHANNEL_NAME };

