import { describe, it, expect, beforeEach } from 'vitest';
import { HistoryStore } from '../../src/modules/history/services/HistoryStore.js';

/**
 * HistoryStore — IDB round-trip + memory fallback + clear.
 * jsdom lacks IndexedDB; the store auto-falls back to MemoryHistoryBackend.
 */
describe('HistoryStore', () => {
    let store;

    beforeEach(async () => {
        store = new HistoryStore({ dbName: 'test-history', storeName: 'ops' });
        await store.init();
    });

    it('falls back to memory backend when IndexedDB is unavailable', () => {
        expect(store.supportsStorageEvents).toBe(false);
    });

    it('persists and retrieves entries', async () => {
        const entry = {
            id: 'e1',
            intent: 'op:a',
            payload: { x: 1 },
            status: 'recorded',
            createdAt: 1000,
            updatedAt: 1000
        };
        await store.put(entry);
        const all = await store.getAll();
        expect(all).toHaveLength(1);
        expect(all[0]).toEqual(entry);
    });

    it('overwrites an entry on put with same id', async () => {
        await store.put({ id: 'e1', intent: 'op:a', status: 'recorded', createdAt: 1, updatedAt: 1 });
        await store.put({ id: 'e1', intent: 'op:a', status: 'undone', createdAt: 1, updatedAt: 2 });
        const all = await store.getAll();
        expect(all).toHaveLength(1);
        expect(all[0].status).toBe('undone');
    });

    it('deletes by id', async () => {
        await store.put({ id: 'e1', intent: 'op:a', status: 'recorded', createdAt: 1, updatedAt: 1 });
        await store.put({ id: 'e2', intent: 'op:b', status: 'recorded', createdAt: 2, updatedAt: 2 });
        await store.delete('e1');
        const all = await store.getAll();
        expect(all).toHaveLength(1);
        expect(all[0].id).toBe('e2');
    });

    it('clears all entries', async () => {
        await store.put({ id: 'e1', intent: 'op:a', status: 'recorded', createdAt: 1, updatedAt: 1 });
        await store.put({ id: 'e2', intent: 'op:b', status: 'recorded', createdAt: 2, updatedAt: 2 });
        await store.clear();
        expect(await store.getAll()).toHaveLength(0);
    });

    it('returns newest-first order from getAll', async () => {
        await store.put({ id: 'old', intent: 'op:a', status: 'recorded', createdAt: 100, updatedAt: 100 });
        await store.put({ id: 'new', intent: 'op:b', status: 'recorded', createdAt: 200, updatedAt: 200 });
        const all = await store.getAll();
        expect(all[0].id).toBe('new');
        expect(all[1].id).toBe('old');
    });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { EventBus } from '../../src/runtime/EventBus.js';
import { HistoryService } from '../../src/modules/history/services/HistoryService.js';

/**
 * BroadcastSync — multi-tab cross-instance sync via BroadcastChannel.
 * jsdom doesn't ship BroadcastChannel; we mock the global with an
 * in-process bus shared between instances.
 */
describe('HistoryService broadcast', () => {
    let originalBC;
    let channels;

    beforeEach(() => {
        originalBC = globalThis.BroadcastChannel;
        channels = new Map(); // channelName -> Set of BroadcastChannel instances
        globalThis.BroadcastChannel = class MockBroadcastChannel {
            constructor(name) {
                this.name = name;
                this.listeners = new Set();
                if (!channels.has(name)) channels.set(name, new Set());
                channels.get(name).add(this);
            }
            addEventListener(type, listener) {
                if (type === 'message') this.listeners.add(listener);
            }
            removeEventListener(type, listener) {
                this.listeners.delete(listener);
            }
            postMessage(data) {
                const peers = channels.get(this.name);
                if (!peers) return;
                for (const peer of peers) {
                    if (peer === this) continue;
                    for (const listener of peer.listeners) {
                        listener({ data });
                    }
                }
            }
            close() {
                channels.get(this.name)?.delete(this);
            }
        };
    });

    afterEach(() => {
        globalThis.BroadcastChannel = originalBC;
    });

    it('two HistoryService instances sync via BroadcastChannel', async () => {
        const eventBus1 = new EventBus();
        const eventBus2 = new EventBus();
        const h1 = new HistoryService(eventBus1);
        const h2 = new HistoryService(eventBus2);

        // Both target the same logical store name so the broadcast channel matches.
        await h1.init({ broadcast: true, broadcastChannel: 'shared-test', broadcast: true });
        await h2.init({ broadcast: true, broadcastChannel: 'shared-test' });

        // H1 records an entry → H2 should reload and see it.
        // (Both use the memory backend; they don't share an IDB store. To simulate
        // shared persistence, we share the same store instance.)
        // For this test we only verify the broadcast reaches the peer; the actual
        // reload-from-store path is exercised in integration tests.
        const h2ReloadSpy = vi.spyOn(h2, '_reloadFromStore');

        h1.record('op:broadcast', {});

        // BroadcastChannel messages are synchronous in our mock.
        expect(h2ReloadSpy).toHaveBeenCalled();

        h1.destroy();
        h2.destroy();
    });

    it('disables broadcast when broadcast:false', async () => {
        const eventBus = new EventBus();
        const history = new HistoryService(eventBus);
        await history.init({ broadcast: false });
        expect(history.broadcastSync).toBeNull();
        history.destroy();
    });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { EventBus } from '../../src/runtime/EventBus.js';
import { Contracts as CoreContracts } from '../../src/runtime/Contracts.js';
import { HistoryContracts } from '../../src/modules/history/contracts/history-contracts.js';
import { HistoryService } from '../../src/modules/history/services/HistoryService.js';

/**
 * History contracts — payload validation for each HISTORY_* event.
 */
describe('history contracts', () => {
    let eventBus;
    let history;

    beforeEach(async () => {
        eventBus = new EventBus();
        eventBus.contracts = { ...CoreContracts, ...HistoryContracts };
        history = new HistoryService(eventBus);
        await history.init({ broadcast: false });
    });

    it('accepts the canonical HISTORY_OP_RECORDED shape published by HistoryService', () => {
        const events = [];
        eventBus.subscribe('HISTORY_OP_RECORDED', (p) => events.push(p));
        history.record('op:a', { x: 1 });
        expect(events).toHaveLength(1);
    });

    it('accepts a minimal store-routing shape on HISTORY_OP_RECORDED', () => {
        // agent-context and other consumers may publish a routing hint without
        // the full entry object. The contract must accept this for testing
        // and bridging scenarios.
        const events = [];
        eventBus.subscribe('HISTORY_OP_RECORDED', (p) => events.push(p));
        expect(() => eventBus.publish('HISTORY_OP_RECORDED', { store: 'maps' }))
            .not.toThrow();
        expect(events).toHaveLength(1);
    });

    it('accepts HISTORY_OP_UNDONE payload', () => {
        const events = [];
        eventBus.subscribe('HISTORY_OP_UNDONE', (p) => events.push(p));
        history.record('op:a', {});
        history.undo();
        expect(events).toHaveLength(1);
        expect(events[0].cursor).toBe(history.cursor);
    });

    it('accepts HISTORY_OP_REDONE payload', () => {
        const events = [];
        eventBus.subscribe('HISTORY_OP_REDONE', (p) => events.push(p));
        history.record('op:a', {});
        history.undo();
        history.redo();
        expect(events).toHaveLength(1);
    });

    it('emits HISTORY_LOG_READY on init with count', () => {
        const events = [];
        const localBus = new EventBus();
        localBus.contracts = { ...CoreContracts, ...HistoryContracts };
        localBus.subscribe('HISTORY_LOG_READY', (p) => events.push(p));
        const h = new HistoryService(localBus);
        return h.init({ broadcast: false }).then(() => {
            expect(events).toHaveLength(1);
            expect(events[0].count).toBe(0);
        });
    });

    it('rejects HISTORY_OP_UNDONE with malformed payload (missing entry)', () => {
        // The contract requires `entry: { id, intent }`. An empty payload should fail.
        expect(() => eventBus.publish('HISTORY_OP_UNDONE', {})).toThrow();
    });

    it('rejects HISTORY_LOG_READY with missing count', () => {
        expect(() => eventBus.publish('HISTORY_LOG_READY', {})).toThrow();
    });
});

